class Solution:
    def minOperations(self, nums: list[int]) -> int:
        n = len(nums)
        unique = sorted(set(nums))
        ans = n
        r = 0
        for l in range(len(unique)):
            while r < len(unique) and unique[r] <= unique[l] + n - 1:
                r += 1
            count = r - l
            ans = min(ans, n - count)
        return ans

class Solution {
public:
    int minOperations(vector<int>& nums) {
        int n = nums.size();
        set<int> st(nums.begin(), nums.end());
        vector<int> unique(st.begin(), st.end());
        int ans = n;
        int r = 0;
        for (int l = 0; l < (int)unique.size(); ++l) {
            while (r < (int)unique.size() && unique[r] <= unique[l] + n - 1) {
                r++;
            }
            int count = r - l;
            ans = min(ans, n - count);
        }
        return ans;
    }
};

class Solution {
    public int minOperations(int[] nums) {
        int n = nums.length;
        Arrays.sort(nums);
        int m = 1;
        for (int i = 1; i < n; i++) {
            if (nums[i] != nums[i - 1]) nums[m++] = nums[i];
        }
        int ans = n;
        int r = 0;
        for (int l = 0; l < m; l++) {
            while (r < m && nums[r] <= nums[l] + n - 1) {
                r++;
            }
            int count = r - l;
            ans = Math.min(ans, n - count);
        }
        return ans;
    }
}

var minOperations = function(nums) {
  const n = nums.length;
  const unique = Array.from(new Set(nums)).sort((a, b) => a - b);
  let ans = n;
  let r = 0;
  for (let l = 0; l < unique.length; l++) {
    while (r < unique.length && unique[r] <= unique[l] + n - 1) {
      r++;
    }
    const count = r - l;
    ans = Math.min(ans, n - count);
  }
  return ans;
};
